def investigate(context, acquire):
    capacity = context['capacity']
    events = context['events']
    order = []
    hits = 0
    misses = 0
    for event in events:
        if event['op'] == 'reset':
            order = []
            hits = 0
            misses = 0
        else:
            key = event['key']
            if key in order:
                order.remove(key)
                order.append(key)
                hits = hits + 1
            else:
                misses = misses + 1
                if len(order) == capacity:
                    order.pop(0)
                order.append(key)
    return {'hits': hits, 'misses': misses, 'size': len(order)}

